UPDATE program
SET title=#{title},body=#{body},status=#{status},opens_at=#{opensAt},closes_at=#{closesAt},max_amount=#{maxAmount},target_text=#{targetText},support_text=#{supportText},exclusion_text=#{exclusionText},selection_text=#{selectionText},contact_text=#{contactText},version=version+1
WHERE id=#{id}
AND version=#{version}
